local _, P = ...
P.Data = {["version"]="0.22.0-prototype",["reviewed"]="2026-10-20",["sources"]={["forever"]="https://foreverchanges.pro/bis/priest/holy",["api"]="https://atraeau.github.io/WoW-Addons/",["classic"]="https://www.icy-veins.com/wow-classic/leveling-guide",["alliance"]="https://www.warcrafttavern.com/wow-classic/guides/alliance-leveling-guide/",["horde"]="https://www.warcrafttavern.com/wow-classic/guides/horde-leveling-guide",["priest"]="https://www.icy-veins.com/wow-classic/classic-priest-leveling-guide",["zf"]="https://www.icy-veins.com/wow-classic/zul-farrak-quests-guide",["st"]="https://www.icy-veins.com/wow-classic/sunken-temple-quests-guide",["quests30"]="https://www.wow-pro.com/james-alliance-leveling-guide-chapter-i-30-41-old-version/",["quests40"]="https://www.wow-pro.com/james-alliance-leveling-guide-chapter-ii-40-50/",["quests50"]="https://www.wow-pro.com/james-horde-leveling-guide-chapter-iv-51-60-old-version-1-2/",["starter"]="https://www.wowhead.com/classic/quest=783/a-threat-within",["crystals"]="https://www.wowhead.com/classic/quest=4284/crystals-of-power",["tirion"]="https://www.wowhead.com/classic/quest=5542/demon-dogs",["core"]="https://www.wowhead.com/classic/guide/classic-wow-attunements-and-keys-dungeons-raids",["defias"]="https://foreverchanges.pro/quest/166",["undeadStart"]="https://www.wowhead.com/classic/quest=363/rude-awakening",["trollStart"]="https://www.wowhead.com/classic/quest=4641/your-place-in-the-world",["candles"]="https://www.wowhead.com/classic/quest=60/kobold-candles",["chill"]="https://www.wowhead.com/classic/quest=375/the-chill-of-death",["oases"]="https://www.wowhead.com/classic/quest=870/the-forgotten-pools",["wcQuests"]="https://www.wowhead.com/classic/guide/classic-wow-wailing-caverns-dungeon-quests",["ashenvale"]="https://www.wowhead.com/classic/quest=6383/the-ashenvale-hunt",["priestQuests"]="https://www.icy-veins.com/wow-classic/priest-quests-in-wow-classic",["classicWeapons"]="https://www.wowhead.com/classic/guide/wow-classic-best-priest-weapons",["foreverWands"]="https://www.icy-veins.com/wow-forever/frost-mage-leveling",["fireWand"]="https://foreverchanges.pro/item/5069",["gravestone"]="https://foreverchanges.pro/item/7001",["smQuests"]="https://www.icy-veins.com/wow-classic/scarlet-monastery-quests-guide",["smLibrary"]="https://www.icy-veins.com/wow-classic/scarlet-monastery-library-dungeon-guide",["wandProgression"]="https://www.warcrafttavern.com/wow-classic/guides/priest-leveling-guide/",["morrow"]="https://www.wowhead.com/classic/quest=2942/the-morrow-stone",["tailoringClassic"]="https://www.wowhead.com/classic/guide/tailoring-leveling-1-300-wow-classic",["smokey"]="https://www.wowhead.com/classic/quest=6041/when-smokey-sings-i-get-violent",["truefaith"]="https://www.wowhead.com/classic/item=14512/pattern-truefaith-vestments",["benediction"]="https://www.icy-veins.com/wow-classic/benediction-anathema-quest-guide-to-the-balance-of-light-and-shadow"},["profiles"]={["PRIEST"]={"Holy","Shadow","Discipline"},["WARRIOR"]={"Arms","Fury","Protection"},["MAGE"]={"Arcane","Fire","Frost"},["ROGUE"]={"Assassination","Combat","Subtlety"},["WARLOCK"]={"Affliction","Demonology","Destruction"},["HUNTER"]={"Beast Mastery","Marksmanship","Survival"},["PALADIN"]={"Holy","Protection","Retribution"},["SHAMAN"]={"Elemental","Enhancement","Restoration"},["DRUID"]={"Balance","Feral","Restoration"}},["stages"]={{["id"]="level-01",["min"]=1,["max"]=5,["title"]="Learn the character",["alliance"]="Starting settlement",["horde"]="Starting settlement",["status"]="Classic-derived; Forever route unverified",["tasks"]={{["id"]="level-01-solo",["mode"]="solo",["text"]="Human example: A Threat Within -> Kobold Camp Cleanup. Other races should finish their own starter chain, then class introductions."},{["id"]="level-01-group",["mode"]="group",["text"]="Only nearby shared objectives; no dungeon priority."},{["id"]="level-01-gear",["mode"]="solo",["text"]="Replace missing basic armor; keep a usable weapon. Priest: start looking for a wand."},{["id"]="level-01-craft",["mode"]="solo",["text"]="Train professions when available; gather locally rather than travel for recipes."},{["id"]="level-01-gates",["mode"]="solo",["text"]="Complete race-specific introductions before leaving; class training takes priority."}},["sources"]={"classic","alliance","horde","starter","undeadStart","trollStart","classicWeapons","foreverWands"},["milestones"]={["alliance"]="Human starting example: A Threat Within, then Kobold Camp Cleanup. Dwarf and Night Elf characters should finish their own starting-area introductions before choosing a travel route.",["horde"]="Undead starting example: Rude Awakening. Orc/Troll starting example: Your Place In The World. Follow your own starting-area chain rather than traveling to another race's start.",["gear"]="Priest planning: at Classic level 5, check Lesser Magic Wand as an early damage goal. It is a planning reference, not a bundled Forever item benchmark; keep any usable starting weapon until the live requirement is confirmed.",["craft"]="Consider an enchanter-made Lesser Magic Wand or a low-cost purchase when available. Do not change professions or spend travel money solely because a Classic guide names the item.",["gate"]="Finish your race's starter handoffs and class introduction. A named starting example is not a cross-race quest offer.",["sources"]={"starter","undeadStart","trollStart","classicWeapons","foreverWands"},["roleClass"]="PRIEST",["evidence"]="Classic planning references; Forever eligibility, values and difficulty unverified unless specifically source-labeled."}},{["id"]="level-06",["min"]=6,["max"]=10,["title"]="Finish the starter zone",["alliance"]="Elwynn / Dun Morogh / Teldrassil",["horde"]="Durotar / Mulgore / Tirisfal",["status"]="Classic-derived; Forever route unverified",["tasks"]={{["id"]="level-06-solo",["mode"]="solo",["text"]="Finish local quest chains and class unlock introductions before moving to a second zone."},{["id"]="level-06-group",["mode"]="group",["text"]="Ask for help with elite finales; skip them if a group takes too long."},{["id"]="level-06-gear",["mode"]="solo",["text"]="Weapon or wand upgrades first; useful stamina and class primary stats next."},{["id"]="level-06-craft",["mode"]="solo",["text"]="Save cloth for bags, bandages or tailoring. Keep money for skills."},{["id"]="level-06-gates",["mode"]="solo",["text"]="Visit the class trainer; Classic class unlock levels are not guaranteed in Forever."}},["sources"]={"classic","alliance","horde","candles","chill","priestQuests","fireWand","classicWeapons"},["milestones"]={["alliance"]="Elwynn example: combine Kobold Candles with Gold Dust Exchange when offered. Other starting zones should finish their local chain before a long trip to Westfall.",["horde"]="Tirisfal example: The Chill of Death can be planned with nearby Brill errands; confirm the required thread and pelts in the quest log. Durotar characters should finish their own local chain.",["classQuest"]="Priest-only Classic level-10 checks: Human/Dwarf Desperate Prayer, Night Elf Returning Home, Troll Hex of Weakness, Undead Touch of Weakness. Forever's racial-spell rules must be checked at the trainer.",["gear"]="Retain or inspect an affordable Lesser Magic Wand. The source-confirmed Forever Fire Wand (ID 5069) requires level 7, but its acquisition source was not established; do not invent a vendor or farming trip.",["craft"]="Save cloth for useful bags or your chosen profession. Compare the cost of buying an early wand with crafting it; recipe access and live profession rules are not inferred.",["gate"]="Class training and a safe exit from the starting zone take priority over optional elite finales. Confirm the actual wand requirement and weapon training.",["sources"]={"candles","chill","priestQuests","fireWand","classicWeapons"},["roleClass"]="PRIEST",["evidence"]="Classic planning references; Forever eligibility, values and difficulty unverified unless specifically source-labeled."}},{["id"]="level-11",["min"]=11,["max"]=15,["title"]="Build efficient loops",["alliance"]="Westfall / Loch Modan / Darkshore",["horde"]="The Barrens / Silverpine",["status"]="Classic-derived; Forever route unverified",["tasks"]={{["id"]="level-11-solo",["mode"]="solo",["text"]="Batch quests by location. Alliance: begin The Defias Brotherhood setup; Horde: build Crossroads or Sepulcher quest loops."},{["id"]="level-11-group",["mode"]="group",["text"]="Ragefire Chasm is a Horde candidate; collect available city quests before a run."},{["id"]="level-11-gear",["mode"]="solo",["text"]="Aim for a reliable damage weapon or wand; avoid buying an entire temporary set."},{["id"]="level-11-craft",["mode"]="solo",["text"]="Craft bags and low-cost consumables; buy recipes only if usable soon."},{["id"]="level-11-gates",["mode"]="solo",["text"]="Faction and prior quest completion govern chain offers; verify quest text in game."}},["sources"]={"classic","alliance","horde","defias","oases","wcQuests","classicWeapons","foreverWands"},["milestones"]={["alliance"]="Westfall example: advance The Defias Brotherhood handoffs while combining local quest loops. Do not enter Deadmines with only the first chain step in your log.",["horde"]="Crossroads example: start The Forgotten Pools and the oases investigations. This is preparation toward the later Leaders of the Fang dungeon quest, not an instruction to enter Wailing Caverns immediately.",["gear"]="Priest planning: Greater Magic Wand is a Classic level-13 milestone. A Forever guide also reports it at 13; actual price, binding, usability and improvement over your owned wand still require inspection.",["craft"]="The Forever guide reports Greater Magic Wand at Enchanting 70. Check the live recipe or ask an enchanter; purchase may cost less than training a profession just for this item.",["gate"]="Defias and oases handoffs must be progressed before their final dungeon objectives. Minimum quest levels do not establish a safe party level.",["sources"]={"defias","oases","wcQuests","classicWeapons","foreverWands"},["roleClass"]="PRIEST",["evidence"]="Classic planning references; Forever eligibility, values and difficulty unverified unless specifically source-labeled."}},{["id"]="level-16",["min"]=16,["max"]=20,["title"]="First dungeon payoff",["alliance"]="Westfall / Redridge / Darkshore",["horde"]="The Barrens / Stonetalon / Silverpine",["status"]="Classic-derived; Forever route unverified",["tasks"]={{["id"]="level-16-solo",["mode"]="solo",["text"]="Finish local non-elite chains. Alliance: advance Defias preparations; Horde: gather Wailing Caverns quests."},{["id"]="level-16-group",["mode"]="group",["text"]="Deadmines (Alliance) or Wailing Caverns; Shadowfang Keep when party-ready. Complete quest objectives in one visit."},{["id"]="level-16-gear",["mode"]="solo",["text"]="Holy Priest: Pristine Gloves is a verified level-15+ candidate, Tailoring 75 and maker-only; keep a usable damage weapon or wand."},{["id"]="level-16-craft",["mode"]="solo",["text"]="Spend on consumables for the planned run; use gathered cloth before buying materials."},{["id"]="level-16-gates",["mode"]="solo",["text"]="The Defias Brotherhood has a preceding Westfall chain; Staff of Westfall is a source-listed reward, eligibility needs live confirmation."}},["sources"]={"classic","alliance","horde","forever","defias","wcQuests","priestQuests"},["milestones"]={["alliance"]="Finish the supported Defias chain, collect its final dungeon quest and plan one prepared Deadmines visit. Staff of Westfall is a source-backed acquisition candidate; check weapon training before selecting it.",["horde"]="Progress the oases investigation and its Thunder Bluff handoffs before Leaders of the Fang. Collect Serpentbloom if offered before the Wailing Caverns run; do not assume the group can finish every collection in one visit.",["gear"]="Holy Priest: compare the verified Pristine Gloves record with what you own. For a Classic Horde weapon reference, Crescent Staff is a Leaders of the Fang reward; its Forever stats and eligibility are not bundled as a benchmark.",["classQuest"]="At Classic level 20, Priest racial quest checks differ by race: A Lack of Fear, Arcane Feedback, Elune's Grace, Shadowguard or Devouring Plague. Treat these as trainer checks in Forever, not guaranteed unlocks.",["craft"]="Pristine Gloves is a source-confirmed level-15 item with Tailoring 75 and a maker restriction. Confirm pattern access and materials before reserving funds.",["gate"]="Plan the dungeon around all party members' actual readiness. A quest reward may be one-time; choose it deliberately and avoid duplicate acquisition if already owned.",["sources"]={"defias","wcQuests","forever","priestQuests"},["roleClass"]="PRIEST",["evidence"]="Classic planning references; Forever eligibility, values and difficulty unverified unless specifically source-labeled."}},{["id"]="level-21",["min"]=21,["max"]=25,["title"]="Prepare the midlevel set",["alliance"]="Duskwood / Wetlands / Redridge",["horde"]="Hillsbrad / Stonetalon / Ashenvale",["status"]="Classic-derived; Forever route unverified",["tasks"]={{["id"]="level-21-solo",["mode"]="solo",["text"]="Alliance: investigate The Fury Runs Deep setup. Both factions: prioritize yellow quests and collect travel connections."},{["id"]="level-21-group",["mode"]="group",["text"]="Stockade for Alliance, Blackfathom Deeps or Shadowfang Keep for a prepared party. Avoid repeating a run for a tiny gain."},{["id"]="level-21-gear",["mode"]="solo",["text"]="Holy Priest: Pristine Leggings becomes wearable at 25; plan materials and profession gates first."},{["id"]="level-21-craft",["mode"]="solo",["text"]="If committed to tailoring, plan skill 125 for the leggings. Do not assume another crafter can supply a maker-only item."},{["id"]="level-21-gates",["mode"]="solo",["text"]="Collect prerequisite quests before traveling; the Stockade reward route is Alliance only."}},["sources"]={"classic","alliance","horde","forever","ashenvale","gravestone","wcQuests"},["milestones"]={["alliance"]="Collect The Fury Runs Deep if eligible before a Stockade outing. For ordinary leveling, choose nearby Wetlands or Duskwood work rather than repeatedly traveling for an isolated item.",["horde"]="The Ashenvale Hunt is a named Splintertree Post objective to investigate when offered. Its creature targets can require help; do not treat the band as a soloability guarantee.",["gear"]="Prepare Pristine Leggings for level 25 only if the maker/profession gates fit your plan. Gravestone Scepter is a source-confirmed Forever item tied to Blackfathom Villainy for both factions; it is a quest-planning reference here, not a proven current-level ranking.",["craft"]="Check Tailoring 125, maker restrictions and the disputed Pristine Leggings recipe source before buying materials. Avoid crafting it if an owned alternative already meets your needs.",["gate"]="Collect available Blackfathom or Stockade quests before entry. The source lists Blackfathom Villainy from Classic level 18, but party readiness and live availability remain separate checks.",["sources"]={"forever","ashenvale","gravestone","wcQuests"},["roleClass"]="PRIEST",["evidence"]="Classic planning references; Forever eligibility, values and difficulty unverified unless specifically source-labeled."}},{["id"]="level-26",["min"]=26,["max"]=30,["title"]="Use the verified Holy sample",["alliance"]="Duskwood / Wetlands / early Stranglethorn",["horde"]="Hillsbrad / Thousand Needles / Ashenvale",["status"]="Classic-derived; Forever route unverified",["tasks"]={{["id"]="level-26-solo",["mode"]="solo",["text"]="Keep ordinary questing moving. Alliance: The Grand Betrayal; Horde: Rig Wars are dungeon quest candidates, not solo errands."},{["id"]="level-26-group",["mode"]="group",["text"]="Razorfen Kraul for Death Speaker Robes at 26; Gnomeregan after gathering quests and checking boss difficulty."},{["id"]="level-26-gear",["mode"]="solo",["text"]="Holy Priest: compare the bundled legs, chest and level-30 boots targets. Other profiles: verified gear data missing."},{["id"]="level-26-craft",["mode"]="solo",["text"]="Tailoring 150 enables the Gilded Slippers recipe; reserve materials only after checking maker and workstation requirements."},{["id"]="level-26-gates",["mode"]="solo",["text"]="Leggings: level 25/skill 125; boots: level 30/skill 150. Recipe-source conflict for leggings must be checked in game."}},["sources"]={"classic","alliance","horde","forever"},["milestones"]={["alliance"]="Collect The Grand Betrayal before a planned Gnomeregan run; finish its available handoffs first. Continue the ordinary Wetlands/Duskwood route while forming the group.",["horde"]="Collect Rig Wars before Gnomeregan when available. Consider Razorfen Kraul as a separate prepared outing rather than assuming a Gnomeregan trip also advances its boss goals.",["gear"]="Use the verified Holy sample: Death Speaker Robes at source level 26, Death Speaker Mantle at 27, and Gilded Slippers at 30. Owned items and manual gate status change the adaptive action list.",["craft"]="Gilded Slippers requires source Tailoring 150 and level 30; check maker/workstation requirements. Keep the leggings recipe conflict visible rather than assuming it was resolved.",["gate"]="Quest pickup, dungeon difficulty, item wear level and recipe skill are different gates. Do not pay for a short-lived farm merely to fill a sample target.",["sources"]={"forever"},["roleClass"]="PRIEST",["evidence"]="Classic planning references; Forever eligibility, values and difficulty unverified unless specifically source-labeled."}},{["id"]="level-31",["min"]=31,["max"]=35,["title"]="Resume quest momentum",["alliance"]="Stranglethorn / Arathi / Desolace",["horde"]="Stranglethorn / Arathi / Desolace",["status"]="Classic-derived; Forever route unverified",["tasks"]={{["id"]="level-31-solo",["mode"]="solo",["text"]="In Stranglethorn, start the early Tiger Mastery and Panther Mastery steps at Nesingwary's camp. Complete each preceding step before its follow-up."},{["id"]="level-31-group",["mode"]="group",["text"]="Scarlet Monastery early wings or Razorfen Kraul cleanup, when appropriate for the group."},{["id"]="level-31-gear",["mode"]="solo",["text"]="Replace the weakest slot through quests; the level-30 sample expires after 30 and is not a current BiS list."},{["id"]="level-31-craft",["mode"]="solo",["text"]="Advance chosen professions with gathered materials; retain travel and training funds."},{["id"]="level-31-gates",["mode"]="solo",["text"]="Classic route only; Forever quest chains, rewards and dungeon tuning above 30 are unverified."}},["sources"]={"classic","alliance","horde","quests30","smQuests","smLibrary","tailoringClassic"},["milestones"]={["alliance"]="Use the early Tiger Mastery and Panther Mastery steps as a shared Stranglethorn circuit when suitable. Prepare Mythology of the Titans before a Scarlet Monastery Library visit if offered.",["horde"]="Use the same early mastery circuit when suitable; Into The Scarlet Monastery is a group-quest preparation check from Classic level 33. Test of Lore is worthwhile only if its earlier chain already fits your route.",["gear"]="Classic Priest references: Illusionary Rod or Hypnotic Blade from Arcanist Doan. Their Classic wear levels are around the next part of this band; verify the actual tooltip and compare a dagger plus off-hand as a set. No Forever ranking is asserted.",["craft"]="Review useful bag capacity, such as the Classic Mageweave Bag recipe, using gathered cloth. Do not push an expensive craft only to replace a functional bag or leveling item.",["gate"]="Check Library objectives before travel and obtain the Scarlet Key if your later-wing plan requires it. Do not send an Undead character to Compendium of the Fallen: the Classic guide excludes that race.",["sources"]={"quests30","smQuests","smLibrary","tailoringClassic"},["roleClass"]="PRIEST",["evidence"]="Classic planning references; Forever eligibility, values and difficulty unverified unless specifically source-labeled."}},{["id"]="level-36",["min"]=36,["max"]=40,["title"]="Budget for mobility",["alliance"]="Stranglethorn / Dustwallow / Badlands",["horde"]="Stranglethorn / Dustwallow / Badlands",["status"]="Classic-derived; Forever route unverified",["tasks"]={{["id"]="level-36-solo",["mode"]="solo",["text"]="Continue Tiger Mastery / Panther Mastery follow-ups only when their targets are suitable; defer named elite finales to a party."},{["id"]="level-36-group",["mode"]="group",["text"]="Scarlet Monastery later wings or Razorfen Downs with a prepared party; collect their quests first."},{["id"]="level-36-gear",["mode"]="solo",["text"]="Maintain a strong weapon and role-appropriate armor; preserve funds for mobility and class training."},{["id"]="level-36-craft",["mode"]="solo",["text"]="Make practical consumables. Check live mount and training rules rather than assuming Classic costs."},{["id"]="level-36-gates",["mode"]="solo",["text"]="Dungeon wings differ in difficulty; planning range is not an entry guarantee."}},["sources"]={"classic","alliance","horde","quests30","smQuests","smLibrary","core"},["milestones"]={["alliance"]="In the Name of the Light is a prepared multi-wing Scarlet Monastery objective. Its Classic prerequisite is Down the Scarlet Path; verify the chain before planning the party route.",["horde"]="Into The Scarlet Monastery is the corresponding multi-wing objective. Agree on Library, Armory and Cathedral targets with the group instead of assuming one wing completes it.",["gear"]="Classic quest references: Orb of Lorica for Alliance or Prophetic Cane for Horde as off-hand choices. Keep a strong existing weapon if the complete one-hand/off-hand combination is not clearly better.",["craft"]="Preserve travel and mobility funds. Craft practical bags or consumables only when their live cost and requirements justify the benefit; avoid filling every slot for the sake of a checklist.",["gate"]="Later wings and their bosses are harder than early wings. The Scarlet Key and prior quest chain are preparation checks, not proof your party is ready.",["sources"]={"smQuests","smLibrary","core"},["roleClass"]="PRIEST",["evidence"]="Classic planning references; Forever eligibility, values and difficulty unverified unless specifically source-labeled."}},{["id"]="level-41",["min"]=41,["max"]=45,["title"]="Stack dungeon quests",["alliance"]="Tanaris / Feralas / Hinterlands",["horde"]="Tanaris / Feralas / Hinterlands",["status"]="Classic-derived; Forever route unverified",["tasks"]={{["id"]="level-41-solo",["mode"]="solo",["text"]="In Tanaris, batch Wastewander Justice and Water Pouch Bounty. Prepare Screecher Spirits before the later Mosh'aru dungeon step."},{["id"]="level-41-group",["mode"]="group",["text"]="Prepare Zul'Farrak quests including Gahz'rilla. Defer difficult steps until party-ready."},{["id"]="level-41-gear",["mode"]="solo",["text"]="Target clear weapon or role upgrades; no Forever-verified item targets for this band."},{["id"]="level-41-craft",["mode"]="solo",["text"]="Prepare food, drink and profession consumables for a longer instance."},{["id"]="level-41-gates",["mode"]="solo",["text"]="Classic Gahz'rilla requires level 40. Confirm a party member has the summoning mallet before planning that boss."}},["sources"]={"classic","alliance","horde","zf","quests40","wandProgression"},["milestones"]={["alliance"]="Combine Wastewander Justice and Water Pouch Bounty in a Tanaris circuit. Start Screecher Spirits only when its travel fits the next dungeon plan.",["horde"]="Use the same Tanaris circuit and prepare Gahz'rilla and The Prophecy of Mosh'aru before the coordinated Zul'Farrak visit.",["gear"]="Classic Priest reference: inspect Blackbone Wand at a capital's wand vendor when already visiting. Do not make a long trip or assume it beats a good owned wand; Forever availability and value are unverified.",["craft"]="Stock appropriate food, drink and mana supplies before the run. Ask a crafter or buy only what you will use; the addon does not establish profession-specific potion usability.",["gate"]="Screecher Spirits precedes The Prophecy of Mosh'aru in the Classic chain. Confirm a party member's Mallet of Zul'Farrak before committing to Gahz'rilla.",["sources"]={"quests40","zf","wandProgression"},["roleClass"]="PRIEST",["evidence"]="Classic planning references; Forever eligibility, values and difficulty unverified unless specifically source-labeled."}},{["id"]="level-46",["min"]=46,["max"]=50,["title"]="Finish long chains deliberately",["alliance"]="Tanaris / Hinterlands / Searing Gorge",["horde"]="Tanaris / Hinterlands / Searing Gorge",["status"]="Classic-derived; Forever route unverified",["tasks"]={{["id"]="level-46-solo",["mode"]="solo",["text"]="Finish accessible hub quests and continue Yeh'kinya preparations; skip isolated elite objectives without help."},{["id"]="level-46-group",["mode"]="group",["text"]="Zul'Farrak: complete The Prophecy of Mosh'aru after Screecher Spirits, then plan The Ancient Egg. Jintha'Alor steps need a party."},{["id"]="level-46-gear",["mode"]="solo",["text"]="Use quest rewards to repair weak slots. Keep useful resistance or healing alternatives without calling them BiS."},{["id"]="level-46-craft",["mode"]="solo",["text"]="Train profession ranks when available; craft only upgrades that justify their material cost."},{["id"]="level-46-gates",["mode"]="solo",["text"]="Classic mallet route uses the Sacred Mallet and the Jintha'Alor altar. Confirm Forever steps before making the trip."}},["sources"]={"classic","alliance","horde","zf","morrow","wandProgression","tailoringClassic"},["milestones"]={["alliance"]="The Stave of Equinex leads to The Morrow Stone in the Classic Feralas route. Combine it with nearby work only when the live prerequisites and target difficulty fit.",["horde"]="Continue prepared Tanaris and Feralas objectives; finish The Prophecy of Mosh'aru before advancing The Ancient Egg. Reserve Jintha'Alor or other elite steps for suitable help.",["gear"]="Classic Priest references: Cairnstone Sliver from The Morrow Stone (Alliance) or Noxious Shooter from Noxxion in Maraudon. They are planning examples, not Forever-verified upgrades or guaranteed drops.",["craft"]="Review an eventual Runecloth Bag or other capacity upgrade against its recipe and material cost. Keep a reserve for essential training rather than forcing profession skill gains now.",["gate"]="A dungeon drop is uncertain; a quest reward still needs the entire chain. Keep the source's Sacred Mallet/Jintha'Alor preparation separate from ordinary solo leveling.",["sources"]={"zf","morrow","wandProgression","tailoringClassic"},["roleClass"]="PRIEST",["evidence"]="Classic planning references; Forever eligibility, values and difficulty unverified unless specifically source-labeled."}},{["id"]="level-51",["min"]=51,["max"]=55,["title"]="Prepare the final push",["alliance"]="Un'Goro / Felwood / Searing Gorge",["horde"]="Un'Goro / Felwood / Searing Gorge",["status"]="Classic-derived; Forever route unverified",["tasks"]={{["id"]="level-51-solo",["mode"]="solo",["text"]="Un'Goro: collect for Crystals of Power at J.D. Collie, then investigate The Eastern Pylon and its companion pylon steps when offered."},{["id"]="level-51-group",["mode"]="group",["text"]="Sunken Temple or early Blackrock Depths objectives; coordinate which quests and bosses the party will do."},{["id"]="level-51-gear",["mode"]="solo",["text"]="Build a functional dungeon role set; save expensive endgame crafts until their Forever recipes are verified."},{["id"]="level-51-craft",["mode"]="solo",["text"]="Stock useful consumables and keep a material reserve for confirmed endgame crafts."},{["id"]="level-51-gates",["mode"]="solo",["text"]="Sunken Temple chains may require earlier dungeons and travel. Check quest log and class trainer first."}},["sources"]={"classic","alliance","horde","st","crystals","quests50","zf","wandProgression","tailoringClassic"},["milestones"]={["alliance"]="Batch Crystals of Power with the Eastern, Northern and Western Pylon investigations when offered in Un'Goro. Continue Felwood hubs when the next Un'Goro tasks are unsuitable.",["horde"]="Use the same crystal/pylon circuit; complete needed Yeh'kinya preparations before The God Hakkar in Sunken Temple rather than arriving without the chain.",["gear"]="Classic Priest reference: Rod of Corrosion from Shade of Eranikus in Sunken Temple. Assess the whole role set and actual requirements; the Forever record and drop likelihood are unverified.",["craft"]="Craft or buy a Runecloth Bag only after checking recipe access and useful capacity. Begin budgeting for confirmed lasting crafts; do not buy an expensive Classic endgame recipe on assumption alone.",["gate"]="Crystals of Power is a prerequisite for the pylon steps. Sunken Temple chains can include earlier dungeon objectives and travel; a class quest is not automatically offered to every profile.",["sources"]={"crystals","quests50","st","zf","wandProgression","tailoringClassic"},["roleClass"]="PRIEST",["evidence"]="Classic planning references; Forever eligibility, values and difficulty unverified unless specifically source-labeled."}},{["id"]="level-56",["min"]=56,["max"]=59,["title"]="Convert preparation into access",["alliance"]="Western / Eastern Plaguelands / Winterspring",["horde"]="Western / Eastern Plaguelands / Winterspring",["status"]="Classic-derived; Forever route unverified",["tasks"]={{["id"]="level-56-solo",["mode"]="solo",["text"]="Eastern Plaguelands: batch Demon Dogs, Blood Tinged Skies and Carrion Grubbage from Tirion Fordring. Avoid difficult chain finales without help."},{["id"]="level-56-group",["mode"]="group",["text"]="Blackrock Depths; assess Lower Blackrock Spire, Stratholme and Scholomance with a competent group."},{["id"]="level-56-gear",["mode"]="solo",["text"]="Prioritize dependable quest upgrades and role readiness; no full-BiS percentage is available."},{["id"]="level-56-craft",["mode"]="solo",["text"]="Prepare sustained dungeon supplies. Verify actual level, reputation and recipe gates before investing."},{["id"]="level-56-gates",["mode"]="solo",["text"]="Classic endgame paths are planning candidates; Forever access, tuning and rewards remain unverified."}},["sources"]={"classic","alliance","horde","tirion","smokey","wandProgression","truefaith"},["milestones"]={["alliance"]="Batch Demon Dogs, Blood Tinged Skies and Carrion Grubbage from Tirion Fordring. That's Asking A Lot is a preparation check before When Smokey Sings, I Get Violent.",["horde"]="The same neutral Tirion circuit can fit the final leveling push. Plan the Smokey chain only if its supply costs and dangerous objectives make sense for your character or group.",["gear"]="Classic Priest reference: Smokey's Fireshooter from When Smokey Sings, I Get Violent. Treat a possible reward as a reason to prepare the chain, not a claim that its guarded objectives are safe solo.",["craft"]="Priest-only long-term Classic reference: Truefaith Vestments, a Tailoring 300 craft with a maker/class restriction. Verify Forever recipe availability before reserving rare materials or changing professions.",["gate"]="Keep normal quest mobs separate from elite finales and dungeon access tasks. Keys, party readiness and quest eligibility must be confirmed in the live game.",["sources"]={"tirion","smokey","wandProgression","truefaith"},["roleClass"]="PRIEST",["evidence"]="Classic planning references; Forever eligibility, values and difficulty unverified unless specifically source-labeled."}},{["id"]="level-60",["min"]=60,["max"]=60,["title"]="Begin horizontal progression",["alliance"]="Chosen endgame hubs",["horde"]="Chosen endgame hubs",["status"]="Classic-derived; Forever route unverified",["tasks"]={{["id"]="level-60-solo",["mode"]="solo",["text"]="Audit unfinished access quests and profession goals; choose a small number of rewarding activities."},{["id"]="level-60-group",["mode"]="group",["text"]="If available in Forever and relevant to your group, plan Attunement to the Core during Blackrock Depths. In Classic it unlocks a shortcut, not the only possible raid entrance."},{["id"]="level-60-gear",["mode"]="solo",["text"]="Require a fresh level-60 dataset before identifying BiS; track checklist completion separately from gear quality."},{["id"]="level-60-craft",["mode"]="solo",["text"]="Choose confirmed lasting crafts and enchants after checking current rules and budget."},{["id"]="level-60-gates",["mode"]="solo",["text"]="No verified Forever level-60 target list is bundled. Endgame access and raid availability require live confirmation."}},["sources"]={"classic","alliance","horde","core","truefaith","benediction"},["milestones"]={["alliance"]="If available and relevant, combine Attunement to the Core with an agreed Blackrock Depths route. Choose one access goal and one role-gearing goal for the session.",["horde"]="Use the same neutral attunement planning check if available. Verify your faction's other access chains separately rather than assuming another player's completed prerequisites apply to you.",["gear"]="Classic Priest references: Truefaith Vestments as a profession option and Benediction as a later raid-linked objective. Neither is represented as verified Forever level-60 BiS; the current benchmark is unavailable.",["craft"]="Only commit to a lasting craft or enchant after confirming the live recipe, binding, profession and budget. Keep horizontal role sets separate from a percentage-to-BiS claim.",["gate"]="The Classic Benediction route begins with The Eye of Divinity from Majordomo Executus before The Balance of Light and Shadow. Actual Forever raid access, item availability and tuning are unverified.",["sources"]={"core","truefaith","benediction"},["roleClass"]="PRIEST",["evidence"]="Classic planning references; Forever eligibility, values and difficulty unverified unless specifically source-labeled."}}},["gear"]={{["id"]=2042,["name"]="Staff of Westfall",["slot"]=16,["min"]=14,["max"]=30,["mode"]="group",["faction"]="Alliance",["activity"]="Deadmines / The Defias Brotherhood",["levelNote"]="Quest planning from Classic acceptance level 14; Forever acceptance and wear/training gates unverified",["source"]="https://foreverchanges.pro/item/2042",["acquire"]="Alliance: finish The Defias Brotherhood Westfall prerequisites, collect the dungeon quest and defeat VanCleef with a prepared Deadmines party. Verify live quest availability before travel.",["materials"]="Quest reward; not a repeatable boss-drop farm. Check weapon training and the two-hand/off-hand tradeoff in game.",["questID"]=166,["effort"]="dungeon"},{["id"]=253913,["name"]="Pristine Gloves",["slot"]=10,["min"]=15,["max"]=30,["mode"]="solo",["source"]="https://foreverchanges.pro/item/253913",["acquire"]="Tailoring 75; maker-only. Item page lists pattern for 30 Merchant's Favor at Mivin Shadowweave / Jim'bek; confirm vendor access.",["materials"]="6 Woolen bolts, 4 Fine Thread, 3 Cerulean Dye, 2 Pristine Leather",["effort"]="craft"},{["id"]=6685,["name"]="Death Speaker Mantle",["slot"]=3,["min"]=27,["max"]=30,["mode"]="group",["source"]="https://foreverchanges.pro/item/6685",["acquire"]="Death Speaker Jargba, Razorfen Kraul. Forever wear level 27 differs from Classic 25.",["materials"]="Dungeon drop; obtain with a party.",["effort"]="dungeon",["activity"]="Razorfen Kraul / Death Speaker Jargba"},{["id"]=253987,["name"]="Pristine Leggings",["slot"]=7,["min"]=25,["max"]=30,["mode"]="solo",["source"]="https://foreverchanges.pro/item/253987",["acquire"]="Tailoring 125; maker-only; check Spinning Wheel. Recipe source disputed: list says pattern; item page says 30 Merchant's Favor at Mivin Shadowweave / Jim'bek.",["materials"]="14 Silk bolts, 3 Fine Thread, 8 Cerulean Dye, 8 Pristine Leather, 2 Silver Bars, 3 Greater Astral Essence",["effort"]="craft"},{["id"]=6682,["name"]="Death Speaker Robes",["slot"]=5,["min"]=26,["max"]=30,["mode"]="group",["source"]="https://foreverchanges.pro/item/6682",["acquire"]="Death Speaker Jargba, Razorfen Kraul. Level 26 is wear requirement, not recommended party entry level.",["materials"]="Dungeon drop; obtain with a party.",["effort"]="dungeon",["activity"]="Razorfen Kraul / Death Speaker Jargba"},{["id"]=254001,["name"]="Gilded Slippers",["slot"]=8,["min"]=30,["max"]=30,["mode"]="solo",["source"]="https://foreverchanges.pro/item/254001",["acquire"]="Tailoring 150; trainer recipe; maker-only; check Spinning Wheel before crafting.",["materials"]="8 Mageweave bolts, 4 Heavy Silken Thread, 2 Magenta Dye, 2 Cerulean Dye, 2 Gold Bars",["effort"]="craft"}},["quests"]={{["id"]=65,["name"]="The Defias Brotherhood - step 1",["summary"]="Speak with Wiley in Lakeshire",["previous"]=0,["faction"]="Alliance",["source"]="https://foreverchanges.pro/quest/65",["evidence"]="Source-linked chain; source mixes Classic baseline and observed Forever changes. Live eligibility and difficulty unknown."},{["id"]=132,["name"]="The Defias Brotherhood - step 2",["summary"]="Return the note to Stoutmantle",["previous"]=65,["faction"]="Alliance",["source"]="https://foreverchanges.pro/quest/132",["evidence"]="Source-linked chain; source mixes Classic baseline and observed Forever changes. Live eligibility and difficulty unknown."},{["id"]=135,["name"]="The Defias Brotherhood - step 3",["summary"]="Bring the note to Mathias Shaw",["previous"]=132,["faction"]="Alliance",["source"]="https://foreverchanges.pro/quest/135",["evidence"]="Source-linked chain; source mixes Classic baseline and observed Forever changes. Live eligibility and difficulty unknown."},{["id"]=141,["name"]="The Defias Brotherhood - step 4",["summary"]="Return the report to Stoutmantle",["previous"]=135,["faction"]="Alliance",["source"]="https://foreverchanges.pro/quest/141",["evidence"]="Source-linked chain; source mixes Classic baseline and observed Forever changes. Live eligibility and difficulty unknown."},{["id"]=142,["name"]="The Defias Brotherhood - step 5",["summary"]="Investigate the Defias Messenger",["previous"]=141,["faction"]="Alliance",["source"]="https://foreverchanges.pro/quest/142",["evidence"]="Source-linked chain; source mixes Classic baseline and observed Forever changes. Live eligibility and difficulty unknown."},{["id"]=155,["name"]="The Defias Brotherhood - step 6",["summary"]="Prepare the Defias Traitor escort",["previous"]=142,["faction"]="Alliance",["source"]="https://foreverchanges.pro/quest/155",["evidence"]="Source-linked chain; source mixes Classic baseline and observed Forever changes. Live eligibility and difficulty unknown."},{["id"]=166,["name"]="The Defias Brotherhood - step 7",["summary"]="Defeat VanCleef with a prepared party",["previous"]=155,["faction"]="Alliance",["source"]="https://foreverchanges.pro/quest/166",["evidence"]="Source-linked chain; source mixes Classic baseline and observed Forever changes. Live eligibility and difficulty unknown."},{["id"]=1198,["name"]="In Search of Thaelrid",["summary"]="Find Argent Guard Thaelrid in Blackfathom Deeps",["previous"]=0,["faction"]="Alliance",["source"]="https://foreverchanges.pro/quest/1198",["evidence"]="Linked predecessor on Blackfathom Villainy source page; live eligibility unknown."},{["id"]=1200,["name"]="Blackfathom Villainy",["summary"]="Collect Kelris head with a party and return to Dawnwatcher Selgorm in Darnassus",["previous"]=1198,["faction"]="Alliance",["source"]="https://foreverchanges.pro/quest/1200",["evidence"]="Source-linked two-step chain; client eligibility unknown."},{["id"]=6561,["name"]="Blackfathom Villainy",["summary"]="Check the Horde Blackfathom Villainy quest and live dungeon objectives",["previous"]=0,["faction"]="Horde",["source"]="https://foreverchanges.pro/quest/6561",["chainIncomplete"]=true,["evidence"]="Faction quest ID linked by source item page; direct quest retrieval unavailable; predecessor map incomplete."}},["questRewards"]={{["id"]=7001,["name"]="Gravestone Scepter",["slot"]=18,["min"]=18,["max"]=30,["mode"]="group",["questByFaction"]={["Alliance"]=1200,["Horde"]=6561},["activity"]="Blackfathom Deeps / Blackfathom Villainy",["source"]="https://foreverchanges.pro/item/7001",["acquire"]="Blackfathom Villainy reward choice. Alliance: investigate In Search of Thaelrid then Blackfathom Villainy. Horde: check the live quest chain; predecessor data incomplete.",["materials"]="Quest reward choice, not a repeatable drop. Classic acceptance reference 18; Forever wear, class/training and safe party level unknown.",["levelNote"]="Classic quest planning from 18; Forever wear eligibility unknown"}}}
